def _component_06(data):
    from itertools import product

    packages = data["packages"]
    names = sorted(packages)
    order = sorted(names, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        versions = sorted({row["version"] for row in packages[name]
                           if row["version"] not in blocked.get(name, [])
                           and (name not in pins or row["version"] == pins[name])})
        choices.append([None] + versions)

    def feasible(assignment):
        graph = {}
        for name, version in assignment.items():
            rows = [r for r in packages[name] if r["version"] == version]
            if not rows:
                return False
            deps = []
            for dep in rows[0].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                v = assignment.get(target)
                if v is None or not dep["min"] <= v <= dep["max"]:
                    return False
                deps.append(target)
            graph[name] = deps

        roots = data["roots"]
        for name, bounds in roots.items():
            v = assignment.get(name)
            if v is None or not bounds[0] <= v <= bounds[1]:
                return False

        active, done = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            for other in graph.get(name, []):
                if not visit(other):
                    return False
            active.remove(name)
            done.add(name)
            return True

        if any(not visit(name) for name in graph):
            return False
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(graph.get(name, []))
        return reachable == set(assignment)

    best = None
    best_key = None
    for values in product(*choices):
        assignment = {name: v for name, v in zip(names, values) if v is not None}
        if not feasible(assignment):
            continue
        key = tuple(assignment.get(name, -1) for name in order)
        if best_key is None or key < best_key:
            best, best_key = assignment, key
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _component_07(data):
    from itertools import combinations
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None
    for subset in combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if ids & blocked or not mandatory <= ids:
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not bounds[0] <= counts.get(group, 0) <= bounds[1]
               for group, bounds in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"], job["id"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        selected = sorted(ids)
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value
                or (value == best_value and selected > best_ids)):
            best_ids, best_value = selected, value
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _component_08(data):
    import heapq

    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit.get(data["source"], 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start_state = (data["source"], initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"],) + start_state]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, left)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival,) + next_state)
    return {"arrival": None}


